function ragStatus(job) {
    const businessDaysSince = (date) => {
        const start = new Date(date);
        const end = new Date();
        start.setHours(0, 0, 0, 0);
        end.setHours(0, 0, 0, 0);
        if (start >= end) {
            return 0;
        }
        let businessDays = 0;
        const current = new Date(start);
        while (current < end) {
            const day = current.getDay();
            if (day !== 0 && day !== 6) {
                businessDays++;
            }
            current.setDate(current.getDate() + 1);
        }
        return businessDays;
    };
    const _daysFromCreation = (job) => {
        const openDate = ([...(job.history ?? [])].reverse().find(h => {
            if (typeof h.action === 'string') {
                if (h.action === 'Job reopened')
                    return true;
                try {
                    const parsed = JSON.parse(h.action);
                    return (typeof parsed === 'object' && parsed !== null && parsed.status !== undefined && parsed.status.new === "open");
                }
                catch (e) {
                    return false;
                }
            }
            return false;
        })?.events?.created || job.events.created);
        return Math.floor((Date.now() - openDate.getTime()) / 1000 / 60 / 60 / 24);
    };
    const _businessDaysFromCreation = (job) => {
        const openDate = ([...(job.history ?? [])].reverse().find(h => {
            if (typeof h.action === 'string') {
                if (h.action === 'Job reopened')
                    return true;
                try {
                    const parsed = JSON.parse(h.action);
                    return (typeof parsed === 'object' && parsed !== null && parsed.status !== undefined && parsed.status.new === "open");
                }
                catch (e) {
                    return false;
                }
            }
            return false;
        })?.events?.created || job.events.created);
        return businessDaysSince(new Date(openDate));
    };
    const _dateLastBriefing = (job) => job.briefings.filter(b => b.status !== 'cancelled' && b.date.end < new Date()).sort((a, b) => b.date.end.getTime() - a.date.end.getTime())[0]?.date.end;
    const _businessDaysFromLastBriefing = (job) => _dateLastBriefing(job) ? businessDaysSince(new Date(_dateLastBriefing(job))) : businessDaysSince(new Date(0));
    const _daysFromLastBriefing = (job) => _dateLastBriefing(job) ? Math.floor((Date.now() - _dateLastBriefing(job).getTime()) / 1000 / 60 / 60 / 24) : undefined;
    const _hasFutureBriefings = (job) => job.briefings.filter(b => b.status !== 'cancelled' && b.date.end >= new Date() && (!b.relations.applicationIDs || b.relations.applicationIDs?.length === 0)).length > 0;
    const _dateOnHold = (job) => job.status === 'paused' ? job.positions.filter(p => p.status === 'paused')[0]?.events.updated || job.history.filter(h => h.action === 'Job put on hold' || h.action.match(/"new":"paused"/))[0]?.events.created || job.events.updated || job.events.refreshed : undefined;
    //const _daysFromOnHold = ( job: JOB ) => job.status === 'paused' && _dateOnHold(job) ? Math.floor(( Date.now() - _dateOnHold(job)!.getTime() ) / 1000 / 60 / 60 / 24 ) : undefined;
    const _daysFromOnHold = (job) => job.status === 'paused' && _dateOnHold(job) ? businessDaysSince(_dateOnHold(job)) : undefined;
    const _activePositionsCount = (job) => job.positions.filter(position => position.active).length;
    const _getApplicationStatusDate = (application, status) => {
        if (!application) {
            return undefined;
        }
        return application.events[status] || [...application.history.filter(a => a.status === status)].reverse()[0]?.events.created;
    };
    const _applicationSlotsCount = (job) => {
        const slotsPerEngagement = job.settings.engagement.cvs;
        return job.engagements.filter(e => e.status === 'active').length * slotsPerEngagement;
    };
    const _applicationsActiveCount = (job) => job.engagements.reduce((acc, engagement) => acc + engagement.applications.reduce((acc, application) => acc + (!['withdrawn', 'dropout', 'rejected'].includes(application.status) ? 1 : 0), 0), 0);
    //const _percentageOfApplicationsSubmitted = ( job: JOB ) =>  _applicationSlotsCount(job) > 0 ? Math.floor( ( _applicationsActiveCount(job) / _applicationSlotsCount(job) ) * 100 ) : 0;
    const _applicationsInterviewing = (job) => job.engagements.flatMap(e => e.applications).filter(a => a.status === 'interviewing');
    const _dateLastActiveApplicationInterviewing = (job) => _getApplicationStatusDate(_applicationsInterviewing(job).sort((a, b) => (_getApplicationStatusDate(b, 'interviewing') || new Date(0)).getTime() - (_getApplicationStatusDate(a, 'interviewing') || new Date(0)).getTime())[0], 'interviewing');
    const _daysFromLastActiveApplicationInterviewing = (job) => _dateLastActiveApplicationInterviewing(job) && _dateLastActiveApplicationInterviewing(job).getTime() > 0 ? Math.floor((Date.now() - _dateLastActiveApplicationInterviewing(job).getTime()) / 1000 / 60 / 60 / 24) : undefined;
    const _applicationsUnderOffer = (job) => job.engagements.flatMap(e => e.applications).filter(a => a.status === 'under-offer');
    const _hasApplicationUnderOffer = (job) => _applicationsUnderOffer(job).length > 0;
    const _applicationsPlaced = (job) => job.engagements.flatMap(e => e.applications).filter(a => ['hired', 'placed'].includes(a.status) && (a.events?.placed || a.events?.hired));
    const _hasPlacementLogged = (job) => _applicationsPlaced(job).length > 0;
    let applicationUnderOffer = _hasApplicationUnderOffer(job);
    let placementLogged = _hasPlacementLogged(job);
    let activePositionsCount = _activePositionsCount(job);
    let _job = job;
    if ((placementLogged && activePositionsCount > 0) || (applicationUnderOffer && activePositionsCount > 1)) {
        _job = {
            ..._job,
            engagements: _job.engagements.map(e => ({ ...e, applications: e.applications.filter(a => !['under-offer', 'placed', 'hired'].includes(a.status)) }))
        };
    }
    try {
        const daysFromCreation = _daysFromCreation(_job);
        const businessDaysFromCreation = _businessDaysFromCreation(_job);
        const daysFromLastBriefing = _daysFromLastBriefing(_job);
        const businessDaysFromLastBriefing = _businessDaysFromLastBriefing(_job);
        const daysFromOnHold = _daysFromOnHold(_job);
        const daysFromLastActiveApplicationInterviewing = _daysFromLastActiveApplicationInterviewing(_job);
        //const percentageOfAppplicationsSubmitted = _percentageOfApplicationsSubmitted( _job );
        const applicationsInterviewing = _applicationsInterviewing(_job).length;
        const activeApplicationsCount = _applicationsActiveCount(_job);
        applicationUnderOffer = _hasApplicationUnderOffer(_job);
        placementLogged = _hasPlacementLogged(_job);
        activePositionsCount = _activePositionsCount(_job);
        //const daysFromLatestEvent = Math.min( daysFromCreation, daysFromLastBriefing || Infinity );
        const businessDaysFromLatestEvent = Math.min(businessDaysFromCreation, businessDaysFromLastBriefing);
        if (daysFromCreation <= 3) {
            return { status: 'white', reason: 'Less than 3 days from creation' };
        }
        if (daysFromLastBriefing !== undefined && daysFromLastBriefing <= 3) {
            return { status: 'white', reason: 'Less than 3 days from last briefing' };
        }
        if (_hasFutureBriefings(job)) {
            return { status: 'white', reason: 'Has planned briefings in the future' };
        }
        if (daysFromOnHold !== undefined && daysFromOnHold <= 21) {
            return { status: 'green', reason: 'On hold for less than 21 days' };
        }
        if (daysFromOnHold !== undefined && daysFromOnHold <= 42) {
            return { status: 'amber', reason: 'On hold for 22 to 42 days' };
        }
        if (daysFromOnHold !== undefined && daysFromOnHold > 42) {
            return { status: 'red', reason: 'On hold for more than 42 days' };
        }
        if ((placementLogged && activePositionsCount === 0) || (applicationUnderOffer && activePositionsCount === 1)) {
            return { status: 'green', reason: placementLogged ? 'Placement logged' : 'Application under offer' };
        }
        if (businessDaysFromLatestEvent > 15) {
            if (applicationsInterviewing >= 3) {
                return { status: 'green', reason: 'More than 3 active interviews' };
            }
            if (applicationsInterviewing >= 2) {
                return { status: 'amber', reason: '2 active interviews' };
            }
            if (applicationsInterviewing < 2) {
                return { status: 'red', reason: '1 or less active interviews' };
            }
        }
        if (daysFromLastActiveApplicationInterviewing !== undefined && daysFromLastActiveApplicationInterviewing >= 42) {
            return { status: 'red', reason: 'Last application interviewing more than 42 days ago' };
        }
        if (daysFromLastActiveApplicationInterviewing !== undefined && daysFromLastActiveApplicationInterviewing >= 28) {
            return { status: 'amber', reason: 'Last application interviewing more than 28 days ago' };
        }
        if (daysFromCreation >= 90) {
            return { status: 'white', reason: 'Job older than 90+ days' };
        }
        /*if ( daysFromLatestEvent > 3 )
        {
            if ( percentageOfAppplicationsSubmitted > 50 ) { return { status: 'green', reason: 'More than 50% active applications' }; }
            if ( percentageOfAppplicationsSubmitted >= 25 ) { return { status: 'amber', reason: '25% to 50% active applications'}; }
            if ( percentageOfAppplicationsSubmitted < 25 ) { return { status: 'red', reason: 'Less than 25% active applications'}; }
        }*/
        if (businessDaysFromLatestEvent >= 1 && businessDaysFromLatestEvent <= 5) {
            if (activeApplicationsCount >= 5) {
                return { status: 'green', reason: '5+ active applications in first 5 days' };
            }
            if (activeApplicationsCount >= 3) {
                return { status: 'amber', reason: '3 to 4 active applications in first 5 days' };
            }
            if (activeApplicationsCount < 3) {
                return { status: 'red', reason: '3 or less active applications in first 5 days' };
            }
        }
        if (businessDaysFromLatestEvent >= 6 && businessDaysFromLatestEvent <= 10) {
            if (activeApplicationsCount >= 10) {
                return { status: 'green', reason: '10+ active applications in first 10 days' };
            }
            if (activeApplicationsCount >= 7) {
                return { status: 'amber', reason: '7 to 9 active applications in first 10 days' };
            }
            if (activeApplicationsCount < 7) {
                return { status: 'red', reason: '6 or less active applications in first 10 days' };
            }
        }
        if (businessDaysFromLatestEvent >= 11) {
            if (activeApplicationsCount >= 5) {
                return { status: 'green', reason: '5+ active applications after 11+ days' };
            }
            if (activeApplicationsCount >= 3) {
                return { status: 'amber', reason: '3 to 4 active applications after 11+ days' };
            }
            if (activeApplicationsCount < 3) {
                return { status: 'red', reason: '3 or less active applications after 11+ days' };
            }
        }
        return { status: 'white', reason: 'Fallback' };
    }
    catch (e) {
        return { status: 'white', reason: 'Error' };
    }
}

function normalizeSalaryRange(salary, rateTo, currencyTo, currencyRates, worktimeRate) {
    if (!salary?.range?.min || !salary?.range?.max) {
        return { min: 0, max: 0 };
    }
    return {
        min: salary.range.min * currencyRates[salary.currency] * (worktimeRate[salary.rate] / worktimeRate[rateTo]),
        max: salary.range.max * currencyRates[salary.currency] * (worktimeRate[salary.rate] / worktimeRate[rateTo]),
    };
}

function furthestStage(engagements, positions) {
    const stages = ['posted', 'engaged', 'application', 'interviewing', 'offer', 'placed', 'hired'];
    let i = 0;
    for (let engagement of engagements) {
        if (engagement.status === 'active' && i < 1) {
            i = 1;
        }
        const limitStage = positions.filter(p => p.active).length > 0;
        for (let application of engagement?.applications.filter(a => limitStage ? !['rejected', 'withdrawn', 'dropout', 'transferred', 'placed', 'hired'].includes(a.status) : true) || []) {
            if (application.active && i < 2) {
                i = 2;
            }
            if (application.status === 'interviewing' && i < 3) {
                i = 3;
            }
            if (application.status === 'under-offer' && i < 4) {
                i = 4;
            }
            if (application.status === 'placed' && i < 5) {
                i = 5;
            }
            if (application.status === 'hired' && i < 6) {
                i = 6;
            }
        }
        if (i === 6) {
            break;
        }
    }
    return stages[i];
}
